{"implementation": "def solve(case):
    required_case_fields = ["threshold", "calls"]
    for f in required_case_fields:
        if f not in case:
            raise ValueError(f"Missing required case field: {f}")

    threshold = case["threshold"]
    calls = case["calls"]

    required_call_fields = ["call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"]

    accepted_call_ids = []
    diagnostics = []

    for call in calls:
        for f in required_call_fields:
            if f not in call:
                raise ValueError(f"Missing required call field: {f}")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        gain = loss_without - loss_with
        norm_tokens = max(1, prediction_tokens)
        normalized_gain = gain / norm_tokens

        accepted = bool(parseable) and (normalized_gain >= threshold)

        if accepted:
            accepted_call_ids.append(call_id)

        diagnostics.append({
            "call_id": call_id,
            "accepted": accepted,
            "normalized_gain": round(normalized_gain, 8)
        })

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }
"}
